.container {
  display: flex;
  flex-wrap: wrap;                 /* nowrap (default) | wrap | wrap-reverse */
  justify-content: space-between;  /* along the main axis */
  align-items: center;             /* along the cross axis */
  align-content: flex-start;       /* only matters when items wrap onto several lines */
  height: 70vh;                    /* gives align-items room to work */
}

.parent {
  display: flex;
  justify-content: center;
  align-items: center;
}
